export type GetInstalledEvent = {
    args: string;
    return: boolean;
};
export type GetVersionEvent = {
    args: string;
    return: string;
};
export type OnEventEvent = {
    args: {
        appId: string;
        event: 'install' | 'uninstall';
    };
    return: void;
};
export type HomeyAppsEvents = {
    onEvent: OnEventEvent;
};
export type SDKAppsEvents = {
    getInstalled: GetInstalledEvent;
    getVersion: GetVersionEvent;
};
